const token=location.hash.slice(1);const form=document.querySelector('#trial');
const status=document.querySelector('#status');
form.addEventListener('submit',async event=>{event.preventDefault();const data=new FormData(form);const args=Object.fromEntries(data);args.image=data.has('image');args.cancel=data.has('cancel');try{const response=await fetch('/run?token='+token,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(args)});if(!response.ok)status.textContent='Trial refused: '+response.status;}catch{status.textContent='Evaluation server unavailable';}});
async function refresh(){try{const response=await fetch('/state?token='+token);if(!response.ok)throw new Error();const state=await response.json();const turn=state.snapshot.turn;status.textContent=turn?`${turn.phase} · ${((turn.elapsedMs??0)/1000).toFixed(1)}s total`:'Ready';form.querySelector('button').disabled=state.busy;form.querySelector('option[value=xkiro]').disabled=!state.allowCloud;document.querySelector('#versions').textContent=Object.entries(state.doctor.engines).map(([name,e])=>`${name}: ${e.installed??'unavailable'}${e.matches?'':' (pin mismatch)'}`).join(' · ');document.querySelector('#timeline').textContent=JSON.stringify(state.snapshot,null,2);document.querySelector('#report').textContent=state.reportPath?'Metadata report: '+state.reportPath:'';}catch{status.textContent='Evaluation server unavailable';}setTimeout(refresh,250);}refresh();
